"""Daemon-only PC7 authority persistence backed by append-only schema v2."""
from __future__ import annotations
import hashlib,json,os
from dataclasses import replace
from pathlib import Path
from typing import Any
import apsw
from .research_db import FailClosed, canonical_json, utc_now
from .conditional_delegation import (OwnerConditionalDelegation,ChildProposal,
    DelegationVerifier)
from .authority_runtime import DaemonContext,FrozenBindings

def _sha(x:Any)->str:return hashlib.sha256(canonical_json(x).encode()).hexdigest()
def _owner_key()->bytes:
    p=os.environ.get('P5_OWNER_ED25519_PUBLIC_KEY_FILE','')
    if not p or not Path(p).is_file():raise FailClosed('OWNER_PUBLIC_KEY_NOT_CONFIGURED')
    b=Path(p).read_bytes()
    if len(b)!=32:raise FailClosed('OWNER_PUBLIC_KEY_INVALID')
    return b
def _owner_uid()->int:return int(os.environ.get('P5_OWNER_PEER_UID','-1'))

class AuthorityStore:
 def __init__(self,db_path:Path):self.db_path=db_path
 def _open(self):
  c=apsw.Connection(str(self.db_path));c.set_busy_timeout(2000);c.execute('PRAGMA foreign_keys=ON');return c
 def proposal(self,payload:dict[str,Any],ctx:DaemonContext)->dict[str,Any]:
  b=FrozenBindings(**payload['bindings']).validate();pid=str(payload['proposal_id']);bj=canonical_json(vars(b));now=ctx.recorded_at
  c=self._open()
  try:
   c.execute('BEGIN IMMEDIATE');c.execute('INSERT INTO authority_proposals VALUES(?,?,?,?,?,?,?,?,?)',(pid,b.family_id,b.run_id,b.run_class,b.digest,bj,ctx.session_id,str(payload['expires_at']),now));c.execute("INSERT INTO authority_transitions(proposal_id,from_state,to_state,daemon_recorded_at,daemon_ledger_sequence,immutable_session_id,authenticated_peer_uid,event_sha256) VALUES(?,?,?,?,?,?,?,?)",(pid,'NONE','PROPOSED',now,ctx.ledger_sequence,ctx.session_id,ctx.peer_uid,_sha({'p':pid,'to':'PROPOSED','seq':ctx.ledger_sequence})));c.execute('COMMIT')
  except BaseException:
   if not c.getautocommit():c.execute('ROLLBACK')
   raise
  finally:c.close()
  return {'status':'PASS','proposal_id':pid,'state':'PROPOSED','binding_sha256':b.digest}
 def transition(self,pid:str,target:str,ctx:DaemonContext,observed_binding_sha256:str|None=None)->dict[str,Any]:
  c=self._open()
  try:
   row=c.execute('SELECT binding_sha256,producer_session_id,expires_at FROM authority_proposals WHERE proposal_id=?',(pid,)).fetchone()
   if not row:raise FailClosed('PROPOSAL_NOT_FOUND')
   last=c.execute('SELECT transition_id,to_state,daemon_ledger_sequence FROM authority_transitions WHERE proposal_id=? ORDER BY transition_id DESC LIMIT 1',(pid,)).fetchone();current=last[1]
   wanted={'PROPOSED':'PRECONDITIONS_PASS','PRECONDITIONS_PASS':'HUMAN_OWNER_SIGNED','HUMAN_OWNER_SIGNED':'APPLIED'}.get(current)
   if target!=wanted:raise FailClosed('ILLEGAL_AUTHORITY_TRANSITION')
   if target=='PRECONDITIONS_PASS' and observed_binding_sha256!=row[0]:raise FailClosed('BINDING_MISMATCH')
   if target in {'HUMAN_OWNER_SIGNED','APPLIED'}:
    if ctx.peer_uid!=_owner_uid():raise FailClosed('OWNER_CREDENTIAL_REQUIRED')
    if ctx.session_id==row[1]:raise FailClosed('OWNER_SESSION_SEPARATION_FAILED')
   c.execute('BEGIN IMMEDIATE');c.execute("INSERT INTO authority_transitions(proposal_id,from_state,to_state,daemon_recorded_at,daemon_ledger_sequence,immutable_session_id,authenticated_peer_uid,event_sha256) VALUES(?,?,?,?,?,?,?,?)",(pid,current,target,ctx.recorded_at,ctx.ledger_sequence,ctx.session_id,ctx.peer_uid,_sha({'p':pid,'to':target,'seq':ctx.ledger_sequence})));c.execute('COMMIT')
  except BaseException:
   if not c.getautocommit():c.execute('ROLLBACK')
   raise
  finally:c.close()
  return {'status':'PASS','proposal_id':pid,'state':target}
 def register_delegation(self,payload:dict[str,Any],ctx:DaemonContext)->dict[str,Any]:
  d=OwnerConditionalDelegation(**payload);v=DelegationVerifier(_owner_key());v.verify_signature(d);sig=__import__('base64').b64decode(d.owner_signature)
  c=self._open()
  try:c.execute('INSERT INTO owner_conditional_delegations VALUES(?,?,?,?,?,?,?,?,?,?)',(d.delegation_id,d.owner_identity,d.owner_credential_scheme,canonical_json(d.unsigned_payload()),d.owner_signature,hashlib.sha256(sig).hexdigest(),d.owner_session_id,d.expires_at,d.scope_hash,'ACTIVE'))
  finally:c.close()
  return {'status':'PASS','delegation_id':d.delegation_id,'scope_sha256':d.scope_hash}
 def redeem(self,delegation_id:str,proposal_payload:dict[str,Any],ctx:DaemonContext)->dict[str,Any]:
  c=self._open()
  try:
   r=c.execute('SELECT unsigned_payload_json,owner_signature_b64 FROM owner_conditional_delegations WHERE delegation_id=?',(delegation_id,)).fetchone()
   if not r:raise FailClosed('DELEGATION_NOT_FOUND')
   dd=json.loads(r[0]);dd['owner_signature']=r[1];d=OwnerConditionalDelegation(**dd);p=ChildProposal(**proposal_payload)
   canonical=c.execute('SELECT producer_session_id,binding_json FROM authority_proposals WHERE proposal_id=?',(p.proposal_id,)).fetchone()
   if not canonical:raise FailClosed('PROPOSAL_NOT_FOUND')
   # Never trust a child payload's producer-session claim. Bind redemption to
   # the daemon-recorded session that created the canonical proposal.
   p=replace(p,producer_session_id=canonical[0])
   binding=json.loads(canonical[1])
   if p.family!=binding['family_id'] or p.run_class!=binding['run_class'] or p.evidence_domain!=binding['evidence_domain'] or p.evaluator_hash!=binding['evaluator_sha256']:raise FailClosed('CANONICAL_PROPOSAL_SCOPE_MISMATCH')
   pre=c.execute("SELECT transition_id,daemon_ledger_sequence FROM authority_transitions WHERE proposal_id=? AND to_state='PRECONDITIONS_PASS' ORDER BY transition_id DESC LIMIT 1",(p.proposal_id,)).fetchone()
   if not pre:raise FailClosed('PRECONDITIONS_PASS_ABSENT')
   if c.execute('SELECT 1 FROM owner_delegation_revocations WHERE delegation_id=?',(delegation_id,)).fetchone():raise FailClosed('DELEGATION_REVOKED')
   event=DelegationVerifier(_owner_key()).redeem(d,p,{'to':'PRECONDITIONS_PASS','ledger_sequence':pre[1],'event_id':str(pre[0])},ctx)
   c.execute('BEGIN IMMEDIATE');c.execute("INSERT INTO authority_transitions(proposal_id,from_state,to_state,daemon_recorded_at,daemon_ledger_sequence,immutable_session_id,authenticated_peer_uid,event_sha256) VALUES(?,?,?,?,?,?,?,?)",(p.proposal_id,'PRECONDITIONS_PASS','HUMAN_OWNER_SIGNED',ctx.recorded_at,ctx.ledger_sequence,ctx.session_id,ctx.peer_uid,_sha(event)));tid=c.last_insert_rowid();c.execute('INSERT INTO delegation_redemptions VALUES(?,?,?,?,?,?)',(event['redemption_event_id'],delegation_id,p.proposal_id,pre[0],tid,event['scope_hash']));c.execute('COMMIT')
  except BaseException:
   if not c.getautocommit():c.execute('ROLLBACK')
   raise
  finally:c.close()
  return {'status':'PASS','event':event}
 def revoke(self,delegation_id:str,ctx:DaemonContext)->dict[str,Any]:
  if ctx.peer_uid!=_owner_uid():raise FailClosed('OWNER_CREDENTIAL_REQUIRED')
  eid='revoke-'+_sha({'d':delegation_id,'seq':ctx.ledger_sequence})[:32];c=self._open()
  try:c.execute('INSERT INTO owner_delegation_revocations VALUES(?,?,?,?,?)',(eid,delegation_id,ctx.recorded_at,ctx.ledger_sequence,ctx.peer_uid))
  finally:c.close()
  return {'status':'PASS','event':'OWNER_DELEGATION_REVOKED','revocation_event_id':eid}
 def register_amendment(self,delegation_id:str,amendment_id:str,amendment_hash:str,ctx:DaemonContext)->dict[str,Any]:
  c=self._open()
  try:
   r=c.execute('SELECT unsigned_payload_json,owner_signature_b64 FROM owner_conditional_delegations WHERE delegation_id=?',(delegation_id,)).fetchone()
   if not r:raise FailClosed('DELEGATION_NOT_FOUND')
   if c.execute('SELECT 1 FROM owner_delegation_revocations WHERE delegation_id=?',(delegation_id,)).fetchone():raise FailClosed('DELEGATION_REVOKED')
   dd=json.loads(r[0]);dd['owner_signature']=r[1];d=OwnerConditionalDelegation(**dd);v=DelegationVerifier(_owner_key());v.verify_signature(d)
   observed=[x[0] for x in c.execute('SELECT amendment_id FROM amendment_registrations ORDER BY registration_ordinal')]
   expected=['C','A','B']
   if observed!=expected[:len(observed)] or len(observed)>=3 or amendment_id!=expected[len(observed)]:raise FailClosed('C_A_B_ORDER_VIOLATION')
   if amendment_hash not in d.allowed_amendment_hashes:raise FailClosed('AMENDMENT_HASH_OUTSIDE_DELEGATION')
   eid='amend-'+_sha({'d':delegation_id,'a':amendment_id,'seq':ctx.ledger_sequence})[:32]
   c.execute('INSERT INTO amendment_registrations VALUES(?,?,?,?,?,?,?)',(eid,amendment_id,amendment_hash,len(observed)+1,'PREAUTHORIZED_CONDITIONAL_DELEGATION',delegation_id,ctx.recorded_at))
  finally:c.close()
  return {'status':'PASS','amendment_event_id':eid,'amendment_id':amendment_id,'registration_ordinal':len(observed)+1}

"""P5 PC7 authority/amendment/trial runtime (engineering layer).

The daemon supplies ``peer_uid``, append-only sequence and canonical time.
Producer timestamps and payload role strings are never authorization inputs.
This module has no Research Memory write path; production persistence is the
separate, audited schema migration.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timezone
import hashlib
import json
from typing import Any, Callable


STATES = ("PROPOSED", "PRECONDITIONS_PASS", "HUMAN_OWNER_SIGNED", "APPLIED")
RUN_CLASSES = {"STATISTICAL_TRIAL", "SYNTHETIC_TEST"}


class AuthorityError(RuntimeError):
    pass


class AuthorizationDenied(AuthorityError):
    pass


class BindingMismatch(AuthorityError):
    pass


def canonical_json(value: Any) -> bytes:
    return json.dumps(value, ensure_ascii=False, sort_keys=True,
                      separators=(",", ":"), allow_nan=False).encode("utf-8")


def sha256(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def parse_utc(value: str) -> datetime:
    if not isinstance(value, str) or not value.endswith("Z"):
        raise AuthorityError("daemon time must be RFC3339 UTC")
    parsed = datetime.fromisoformat(value[:-1] + "+00:00")
    if parsed.utcoffset() != timezone.utc.utcoffset(parsed):
        raise AuthorityError("daemon time must be UTC")
    return parsed


@dataclass(frozen=True)
class FrozenBindings:
    family_id: str
    run_id: str
    run_class: str
    evidence_domain: str
    prereg_sha256: str
    dataset_manifest_sha256: str
    revision_lineage_sha256: str
    universe_rule_sha256: str
    validation_contract_sha256: str
    cost_contract: str
    evaluator_sha256: str
    cutoff: str
    wave_id: str | None = None
    candidate_grammar_sha256: str | None = None
    candidate_list_sha256: str | None = None
    candidate_count: int | None = None
    enumerator_sha256: str | None = None
    evaluation_order_sha256: str | None = None
    executable_contract_sha256: str | None = None
    risc_rule: str | None = None
    resource_scope: str | None = None

    def validate(self) -> "FrozenBindings":
        if self.run_class not in RUN_CLASSES:
            raise AuthorityError("unsupported run_class")
        for name, value in vars(self).items():
            if name.endswith("sha256") and value is not None:
                if len(value) != 64 or any(c not in "0123456789abcdef" for c in value):
                    raise AuthorityError(f"invalid {name}")
        if self.wave_id is not None:
            required = (self.wave_id, self.candidate_grammar_sha256,
                        self.candidate_list_sha256, self.enumerator_sha256,
                        self.evaluation_order_sha256,
                        self.executable_contract_sha256, self.risc_rule,
                        self.resource_scope)
            if any(value is None for value in required) or self.candidate_count != 174:
                raise AuthorityError("Wave-1 bindings incomplete")
        return self

    @property
    def digest(self) -> str:
        self.validate()
        return sha256(canonical_json(vars(self)))


@dataclass(frozen=True)
class DaemonContext:
    peer_uid: int
    session_id: str
    recorded_at: str
    ledger_sequence: int

    def validate(self) -> "DaemonContext":
        if not isinstance(self.peer_uid, int) or self.peer_uid < 0:
            raise AuthorityError("invalid daemon peer uid")
        if not self.session_id or not isinstance(self.ledger_sequence, int):
            raise AuthorityError("daemon session/order missing")
        parse_utc(self.recorded_at)
        return self


@dataclass
class AuthorityProposal:
    proposal_id: str
    bindings: FrozenBindings
    producer_session_id: str
    expires_at: str
    state: str = "PROPOSED"
    events: list[dict[str, Any]] = field(default_factory=list)
    applied_grant_id: str | None = None


class AuthorityFSM:
    """Fail-closed FSM whose trust inputs come only from the daemon."""

    def __init__(self, owner_peer_uid: int,
                 daemon_context: Callable[[], DaemonContext]):
        self._owner_peer_uid = owner_peer_uid
        self._daemon_context = daemon_context

    def _ctx(self) -> DaemonContext:
        return self._daemon_context().validate()

    def _append(self, proposal: AuthorityProposal, target: str,
                details: dict[str, Any]) -> None:
        current_index = STATES.index(proposal.state)
        if current_index + 1 >= len(STATES) or STATES[current_index + 1] != target:
            raise AuthorityError(f"illegal transition {proposal.state}->{target}")
        ctx = self._ctx()
        if proposal.events and ctx.ledger_sequence <= proposal.events[-1]["ledger_sequence"]:
            raise AuthorityError("daemon ledger order is not append-only")
        proposal.events.append({
            "from": proposal.state, "to": target,
            "daemon_recorded_at": ctx.recorded_at,
            "ledger_sequence": ctx.ledger_sequence,
            "immutable_session_id": ctx.session_id,
            "peer_uid": ctx.peer_uid,
            "details": details,
        })
        proposal.state = target

    def preconditions_pass(self, proposal: AuthorityProposal,
                           observed_binding_digest: str) -> None:
        if observed_binding_digest != proposal.bindings.digest:
            raise BindingMismatch("precondition binding digest mismatch")
        self._append(proposal, "PRECONDITIONS_PASS",
                     {"binding_digest": observed_binding_digest})

    def human_owner_sign(self, proposal: AuthorityProposal) -> None:
        ctx = self._ctx()
        if ctx.peer_uid != self._owner_peer_uid:
            raise AuthorizationDenied("HUMAN_OWNER_SIGNED requires owner daemon credential")
        if ctx.session_id == proposal.producer_session_id:
            raise AuthorizationDenied("owner session must differ from producer session")
        self._append(proposal, "HUMAN_OWNER_SIGNED",
                     {"owner_peer_uid": ctx.peer_uid})

    def apply(self, proposal: AuthorityProposal) -> str:
        ctx = self._ctx()
        if ctx.peer_uid != self._owner_peer_uid:
            raise AuthorizationDenied("APPLIED requires owner daemon credential")
        if parse_utc(ctx.recorded_at) >= parse_utc(proposal.expires_at):
            raise AuthorizationDenied("grant expired under daemon-authoritative time")
        grant_id = "grant-" + sha256(canonical_json({
            "proposal_id": proposal.proposal_id,
            "binding_digest": proposal.bindings.digest,
            "owner_session": ctx.session_id,
        }))[:32]
        self._append(proposal, "APPLIED", {"grant_id": grant_id})
        proposal.applied_grant_id = grant_id
        return grant_id


@dataclass
class Attempt:
    attempt_id: str
    logical_trial_id: str
    ordinal: int
    state: str = "RUNNING"


class TrialRegistry:
    """One logical wave per grant; infrastructure retries keep its identity."""

    def __init__(self) -> None:
        self._logical_by_grant: dict[str, tuple[str, str]] = {}
        self._attempts: dict[str, list[Attempt]] = {}

    def open_wave(self, grant_id: str, candidate_list_sha256: str) -> Attempt:
        existing = self._logical_by_grant.get(grant_id)
        if existing is None:
            logical = "logical-" + sha256(canonical_json(
                {"grant_id": grant_id, "candidate_list_sha256": candidate_list_sha256}))[:32]
            self._logical_by_grant[grant_id] = (logical, candidate_list_sha256)
            self._attempts[logical] = []
        else:
            logical, frozen_hash = existing
            if frozen_hash != candidate_list_sha256:
                raise BindingMismatch("new candidate list requires a new grant/wave")
        ordinal = len(self._attempts[logical]) + 1
        attempt = Attempt(f"{logical}-attempt-{ordinal:04d}", logical, ordinal)
        self._attempts[logical].append(attempt)
        return attempt

    def void_attempt(self, attempt: Attempt) -> None:
        if attempt.state != "RUNNING":
            raise AuthorityError("only running attempt can be voided")
        attempt.state = "ATTEMPT_VOID"

    def complete(self, attempt: Attempt) -> None:
        if attempt.state != "RUNNING":
            raise AuthorityError("only running attempt can complete")
        if any(a.state == "COMPLETED" for a in self._attempts[attempt.logical_trial_id]):
            raise AuthorityError("duplicate logical result")
        attempt.state = "COMPLETED"

    @property
    def logical_trial_count(self) -> int:
        return len(self._logical_by_grant)

# P5 Amendment D ā€?Autonomous Authority Bridge V1

CANONICAL_ID=P5_AMENDMENT_D_AUTONOMOUS_AUTHORITY_BRIDGE_V1

STATUS=PREPARED_UNREGISTERED

REOPEN_TRIGGER=PART_XII_TRIGGER_3_GENUINELY_AMENDMENT_CLASS_AUTHORITY_CHANGE

SCIENTIFIC_ESTIMAND_RULE_CHANGES=0

SCIENTIFIC_ADJUDICATION_RULE_CHANGES=0

AUTHORITY_GOVERNANCE_RULE_CHANGES=1

## 1. Scope and activation order

This amendment changes only the authorization procedure for one bounded P3 launch chain. It creates no authority while PREPARED_UNREGISTERED.

Exact frozen Amendment C MUST first be registered and APPLIED by a direct human-owner action under the pre-D interactive path. Only after C is APPLIED may exact Amendment D be registered and APPLIED by a distinct direct human-owner action. D cannot authorize, register, replace, bootstrap, or retroactively validate C. D_CAN_AUTHORIZE_C=NO.

The only permitted order is:

1. exact C, direct-owner, APPLIED;
2. exact D, direct-owner, APPLIED;
3. one owner-signed bounded root delegation registered;
4. exact A, then exact B, as two distinct delegated registration events;
5. exact T1-first information-order policy;
6. T1 child authority, execution, and seal;
7. Wave-1 child authority, all 174 frozen candidates, and seal;
8. STOP.

Interactive owner signing remains supported. One owner ceremony may contain multiple cryptographically, session, proposal, and ledger-domain-separated owner operations; one ceremony does not mean one signature or one grant.

## 2. Dormant root delegation

After exact C and D are APPLIED, a human owner may sign one OWNER_CONDITIONAL_DELEGATION. The executing agent and daemon possess no credential capable of creating that owner signature. The root is dormant: registration alone opens no statistical authority and permits no label access.

The root must bind exact C and D APPLIED identities as prerequisites, exact A and B hashes, the current T1 and Wave-1 proposal identities, all frozen scientific/data/evaluator/runtime hashes, exact evidence and information domains, the exact outcome-blind resource policy, expiry and revocation state, and explicit prohibitions. Wildcards, scientific equivalence substitution, future evaluator discretion, and scope expansion are forbidden.

The root cannot register C or D. It may register only exact A followed by exact B, as distinct ledger events, after C and D. T1 and Wave-1 require distinct child proposals and distinct logical grants; neither grant may be reused or merged.

## 3. Child authority redemption

Every delegated child retains the ordered machine ledger path:

`PROPOSED ā†?PRECONDITIONS_PASS ā†?DELEGATION_SCOPE_MATCH ā†?HUMAN_OWNER_SIGNED ā†?APPLIED`.

PRECONDITIONS_PASS is mandatory and cannot be replaced by an owner signature. After PRECONDITIONS_PASS exists, a zero-LLM deterministic verifier may redeem the pre-existing root credential only if every exact scope/hash/session/information/resource predicate matches. The resulting HUMAN_OWNER_SIGNED event occurs after PRECONDITIONS_PASS and records the root credential identity, owner-signature hash, root scope hash, child proposal, precondition event, redemption event, and authorization mode PREAUTHORIZED_CONDITIONAL_DELEGATION.

The human owner is the authorization source. The runtime redeems but does not sign. No event may claim the agent is the owner or signer. Root-owner session identity must differ from every child proposal producer session. Retry cannot create a duplicate logical grant.

Owner revocation is append-only, owner-only, and blocks every subsequent redemption or label gate. Global infrastructure or integrity stops always override delegation. Sealed immutable prior results remain ledgered.

## 4. T1-first continuation

T1 receives the first P3 real-label access. Wave-1 may begin only after the T1 result is sealed. T1 performance is not a Wave-1 permission predicate: REPLICATION_SUPPORTED, REPLICATION_FAILED, and EVIDENCE_INSUFFICIENT_CURRENT_COHORT each permit continuation after seal. TEST_VOIDED or a shared integrity failure blocks continuation until the exact defect is resolved.

No outcome value may influence redemption, resource allocation, candidate order, or early stopping.

## 5. Wave-1 owner resource policy clarification

For this bounded delegated mode, `wave1_grant.wall_time_expiry` is represented by an exact signed object with these semantics:

- `policy_type=WAVE1_CUMULATIVE_ACTIVE_WALL_TIME_V1`;
- `wall_time_expiry_seconds` is a positive integer selected by the owner; no default exists;
- `clock=DAEMON_MONOTONIC_ACTIVE_ATTEMPT_TIME`;
- `starts_at=WAVE1_APPLIED`;
- `accumulation=SUM_ALL_ATTEMPTS_SAME_LOGICAL_WAVE`;
- `checkpoint_semantics=SEALED_PARTIAL_CHECKPOINT_RESUME_ONLY`;
- `on_exhaustion=RESOURCE_EXHAUSTED_OWNER_ACTION_REQUIRED`;
- `scientific_early_stop=false`;
- `candidate_count=174`;
- `decision_basis.source=SEALED_SYNTHETIC_FULL_PATH_BENCHMARK_ONLY`;
- `decision_basis.benchmark_sha256` is the exact sealed benchmark hash;
- `decision_basis.real_p5_labels_read_before_choice=false`.

The owner selects the positive integer after the sealed synthetic benchmark and before any P3 real-label access. The complete resource-policy object is inside signed bytes, included in the root scope hash, immutable after signature, and matched exactly by the Wave-1 child and canonical proposal. It is separate from the security credential's absolute `expires_at`; neither field may substitute for the other.

Resource expiry is an engineering stop, not a scientific outcome or performance early-stop. If expiry occurs before 174/174 completion, no partial H0 scientific report, survivor name, candidate ranking, or adaptive reasoning may be emitted. A sealed partial checkpoint may only resume the same logical wave under an owner-authorized resource policy. The wave remains incomplete and stops as RESOURCE_EXHAUSTED_OWNER_ACTION_REQUIRED. No automatic extension is implied.

## 6. Exact prohibitions

Neither D nor any root or child under D authorizes H2, H2 registration, H2 reveal, D4 reveal, H3, E2, capital, mainnet, exchange private API keys, HOME real-market activation or expansion, GCP infrastructure expansion, S2a, P1, P2, P4, a new family, new candidate, new grammar, new dataset revision, new label window, new direction, post-outcome sign flip, survivor admission, VALIDATED_ALPHA, P5_STRATEGY_PASS, Wave-2, or any scientific-right expansion.

No partial Wave-1 output may enter an LLM or adaptive decision process. No scientific estimand, candidate, data, multiplicity, evidence-domain, H2, D4, H3, or adjudication rule is changed by D.

## 7. Supersession boundary

For the exact bounded delegated mode only, D supersedes the repeated wall-clock human re-entry requirements for A, B, T1, and Wave-1 with a preauthorized cryptographic owner capability. It does not supersede C-first, direct-owner C, direct-owner D, no self-grant, PRECONDITIONS_PASS-first, exact C/A/B text, session and role separation, scientific contracts, evidence law, multiplicity law, information scarcity, or any owner/global stop.

