 SELECT CASE WHEN (SELECT group_concat(identity,'|') FROM (SELECT amendment_id||':'||amendment_sha256||':'||authorization_mode||':'||state AS identity FROM amendment_registrations ORDER BY registration_ordinal))!='C:5b1d8116aa8ed30b407c4804dae191af34a9e4fcc1b9ec292a73b5eeb7c47c83:INTERACTIVE_OWNER_SIGN:APPLIED|D:c419cbdc0bc26670d5c18b37f183a9cd3481b00680f0b10d3176e482ef1d5be4:INTERACTIVE_OWNER_SIGN:APPLIED' THEN RAISE(ABORT,'exact C and D required before root') END;
